import ipaddress
import requests

def task_func(ip_range, timeout):
    try:
        # Validate and create an IPv4 network object from the CIDR range
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError("Invalid IP range provided.") from e

    active_ips = []

    # Iterate over each IP address in the network
    for ip in network.hosts():
        try:
            # Send an HTTP GET request to the IP address
            response = requests.get(f"http://{ip}", timeout=timeout)
            # Check if the response status code is 200
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            # Ignore any request exceptions and continue to the next IP
            continue

    return active_ips

import re
import requests

def task_func(input):
    # Extract the API endpoint using regular expression
    api_endpoint_match = re.search(r'https?://[^\s]+', input)
    if not api_endpoint_match:
        raise ValueError("No valid API endpoint found in the input.")

    api_endpoint = api_endpoint_match.group(0)

    # Send a GET request to the extracted API endpoint
    try:
        response = requests.get(api_endpoint)
        response.raise_for_status()  # Raise an error for bad responses
    except requests.RequestException as e:
        raise Exception(f"Failed to fetch data from {api_endpoint}: {e}")

    # Return the response data in JSON format
    return response.json()
